98	2026-04-03 15:42:11.781115+00	{"pk": 6, "body": "<p>大下智库聚焦能源与气候、汽车与交通、跨文化交流与国际合作等方向，通过文章、专题页和活动议题持续输出研究判断。</p><p>这一页面适合承接研究主题说明、公开内容入口和合作方向介绍，保持简洁、稳定且便于继续扩展。</p>", "live": true, "path": "000100010003", "slug": "thinktank", "depth": 3, "intro": "围绕重点议题、研究观察与合作主题组织公开表达和内容输出。", "owner": null, "title": "大下智库", "locale": 1, "locked": false, "expired": false, "alias_of": null, "numchild": 0, "url_path": "/home/thinktank/", "expire_at": null, "locked_at": null, "locked_by": null, "seo_title": "", "go_live_at": null, "draft_title": "大下智库", "content_type": 35, "live_revision": 11, "show_in_menus": false, "latest_revision": 11, "translation_key": "6c131fde-3220-4adb-af8c-466eaea68e8b", "last_published_at": "2026-04-03T12:04:18.678Z", "first_published_at": "2026-04-03T12:01:58.062Z", "search_description": "", "wagtail_admin_comments": [], "has_unpublished_changes": false, "latest_revision_created_at": "2026-04-03T12:04:18.638Z"}	\N	6	\N	35	1	大下智库
